const items = $input.all();
const html = items[0].json.body || items[0].json.data || '';
// Basic HTML to text extraction
const text = html.toString().replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 8000);
return [{ json: { blogContent: text, blogUrl: items[0].json.body?.blog_url || '' } }];

const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { twitter_thread: [aiResponse], linkedin_post: aiResponse, instagram_caption: aiResponse };
}
const twitterThread = Array.isArray(parsed.twitter_thread) ? parsed.twitter_thread.join('\n\n---\n\n') : parsed.twitter_thread;
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    blogUrl: items[0].json.blogUrl || '',
    twitterThread: twitterThread,
    linkedinPost: parsed.linkedin_post || '',
    instagramCaption: parsed.instagram_caption || '',
    status: 'Draft'
  }
}];
